FILE = "patients_2026-03-01.csv"


def export(patients):
    # The registration system's nightly export, written as a file. Don't change this.
    shutil.rmtree("/tmp/registry", ignore_errors=True)  # start from empty folders on every run
    os.makedirs(INCOMING)

    def text(column, value):
        if column == "birth_date":
            return "00/00/0000" if value is None else value.strftime("%d/%m/%Y")  # day/month/year
        return "" if value is None else str(value)

    lines = [";".join(patients.columns)]
    for row in patients.collect():
        lines.append(";".join(text(c, v) for c, v in zip(patients.columns, row)))
    with open(f"{INCOMING}/{FILE}", "w") as f:
        f.write("\n".join(lines) + "\n")


